import { type CallToolResult } from '@modelcontextprotocol/server';
import { type Config } from '../config.js';

// Upstream JSON cannot mark itself as a locally generated byte envelope.
const inlineBinary = Symbol('inlineBinary');

export function binaryContent(bytes: Buffer | undefined): Record<string, string> | undefined {
    return bytes === undefined ? undefined : { [inlineBinary]: true, encoding: 'base64', base64: bytes.toString('base64') };
}

export function boundResult(result: CallToolResult, config: Config): CallToolResult {
    const secrets = [config.apiToken];
    if (config.proxyURL) {
        const proxy = new URL(config.proxyURL);
        const username = decodeURIComponent(proxy.username), password = decodeURIComponent(proxy.password);
        secrets.push(config.proxyURL, proxy.username, proxy.password, username, password);
        if (username || password) secrets.push(Buffer.from(`${username}:${password}`).toString('base64'));
    }
    const knownSecrets = secrets.filter((secret): secret is string => !!secret).sort((a, b) => b.length - a.length);
    const redact = (value: string) => knownSecrets.reduce((text, secret) => text.replaceAll(secret, '<REDACTED>'), value);
    const original = (result.structuredContent ?? {}) as Record<string, unknown>;
    const literalFields = new Set(['encoding', 'format', 'unit', 'status']);
    const literals = new Set(['utf-8', 'base64', 'codePoints', 'bytes', 'markdown', 'html', 'pdf', 'screenshot', 'rawData', 'processing', 'completed', 'failed', 'expired', 'scraping']);
    const opaqueFields = new Set(['encoding', 'format', 'unit', 'status', 'id', 'taskId', 'crawlId', 'ref', 'markdownRef', 'htmlRef', 'pdfRef', 'screenshotRef', 'rawDataRef', 'nextCursor', 'prevCursor', 'errorCode']);
    let sensitive = false;
    const text = JSON.stringify(original, function (key, value: unknown) {
        if (typeof value !== 'string') return value;
        if (this === original && literalFields.has(key) && literals.has(value)) return value;
        if (this[inlineBinary] === true && key === 'encoding') return value;
        if ((this === original || this[inlineBinary] === true) && this.encoding === 'base64' && (key === 'body' || key === 'base64')) {
            const bytes = Buffer.from(value, 'base64');
            if (knownSecrets.some(secret => bytes.includes(Buffer.from(secret)))) sensitive = true;
            return value;
        }
        const filtered = redact(value);
        if (opaqueFields.has(key) && filtered !== value) { sensitive = true; return value; }
        return filtered;
    });
    if (sensitive) {
        const output = { error: { code: 'SENSITIVE_OUTPUT', message: 'Sensitive binary content or an opaque identifier was withheld instead of corrupting its value.' } };
        return { isError: true, content: [{ type: 'text', text: JSON.stringify(output) }], structuredContent: output };
    }
    const data = JSON.parse(text) as Record<string, unknown>;
    if (text.length <= config.maxOutputChars) {
        return { ...result, content: [{ type: 'text', text }], structuredContent: data };
    }

    const recovery: Record<string, unknown> = {};
    const error = { code: 'OUTPUT_LIMIT', message: 'Result exceeds the local output limit. Reduce source content or use a supported smaller page/chunk/reference. Do not automatically repeat a task submission.', recovery };
    const add = (key: string, value: unknown) => {
        if (typeof value !== 'string' && typeof value !== 'number' && typeof value !== 'boolean') return;
        const candidate = { ...recovery, [key]: value };
        if (JSON.stringify({ error: { ...error, recovery: candidate } }).length <= config.maxOutputChars) Object.assign(recovery, candidate);
    };
    for (const key of ['statusCode', 'id', 'taskId', 'crawlId', 'ref', 'format', 'offset', 'nextCursor', 'prevCursor']) add(key, data[key]);
    if (data.data && typeof data.data === 'object' && !Array.isArray(data.data)) {
        const page = data.data as Record<string, unknown>;
        for (const key of ['markdownRef', 'htmlRef', 'pdfRef', 'screenshotRef', 'rawDataRef']) add(key, page[key]);
        add('truncated', page.truncated);
    }
    const output = { error };
    return { isError: true, content: [{ type: 'text', text: JSON.stringify(output) }], structuredContent: output };
}
